---------------------
---- KEYBINDINGS ----
---------------------

local mainMod = "SUPER"

local function exec(cmd) return hl.dsp.exec_cmd(cmd) end

hl.bind(mainMod .. " + RETURN", exec(terminal))
hl.bind(mainMod .. " + Q",      hl.dsp.window.close())
hl.bind(mainMod .. " + E",      exec(fileManager))
hl.bind(mainMod .. " + R",      exec(terminal .. " ranger"))
hl.bind(mainMod .. " + SPACE",  hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + D",      exec(menu))
hl.bind(mainMod .. " + B",      exec(linuxSetup .. "/rofi-bluetooth/rofi-bluetooth"))
hl.bind(mainMod .. " + N",      exec(linuxSetup .. "/rofi-tailscale.sh"))
hl.bind(mainMod .. " + M",      exec("nwg-displays"))
hl.bind(mainMod .. " + P",      exec("rofi-rbw"))
hl.bind(mainMod .. " + F1",     exec("rofi -show emoji"))
hl.bind(mainMod .. " + F2",     exec(linuxSetup .. "/rofi-wallpaper.sh"))
hl.bind(mainMod .. " + F9",     exec(linuxSetup .. "/rofi-mount.sh mount"))
hl.bind(mainMod .. " + F10",    exec(linuxSetup .. "/rofi-mount.sh unmount"))
hl.bind(mainMod .. " + C",      exec("rofi -show calc"))

hl.bind(mainMod .. " + W",                exec(browser))
hl.bind(mainMod .. " + CTRL + SHIFT + L", exec("hyprlock"))
hl.bind(mainMod .. " + F",                hl.dsp.window.fullscreen())

hl.bind(mainMod .. " + X", exec(linuxSetup .. "/rofi_power_menu.sh"))

local screenshotDir = " -o ~/Pictures/Screenshots/"
hl.bind("PRINT",                     exec("hyprshot --mode active --mode output" .. screenshotDir))
hl.bind("SHIFT + PRINT",             exec("hyprshot --mode window" .. screenshotDir))
hl.bind("CTRL + PRINT",              exec("hyprshot --mode region" .. screenshotDir))
hl.bind(mainMod .. " + SHIFT + S",   exec("hyprshot --mode region" .. screenshotDir))

-- Focus / resize / swap with vim keys
local dirs = { h = "left", l = "right", k = "up", j = "down" }
local resizeDeltas = { h = { -50, 0 }, l = { 50, 0 }, k = { 0, -50 }, j = { 0, 50 } }
for key, dir in pairs(dirs) do
    local d = resizeDeltas[key]
    hl.bind(mainMod .. " + " .. key,           hl.dsp.focus({ direction = dir }))
    hl.bind(mainMod .. " + SHIFT + " .. key,   hl.dsp.window.resize({ x = d[1], y = d[2], relative = true }))
    hl.bind(mainMod .. " + CTRL + " .. key,    hl.dsp.window.swap({ direction = dir }))
end

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key,         hl.dsp.focus({ workspace = i }))
    hl.bind(mainMod .. " + SHIFT + " .. key, hl.dsp.window.move({ workspace = i }))
end

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Multimedia keys for volume and brightness
local lockedRepeat = { locked = true, repeating = true }
hl.bind("XF86AudioRaiseVolume",  exec(linuxSetup .. "/set_volume.sh 5%+"),                 lockedRepeat)
hl.bind("XF86AudioLowerVolume",  exec(linuxSetup .. "/set_volume.sh 5%-"),                 lockedRepeat)
hl.bind("XF86AudioMicMute",      exec("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),     lockedRepeat)
hl.bind("XF86MonBrightnessUp",   exec(linuxSetup .. "/set_brightness.sh 5%+"),             lockedRepeat)
hl.bind("XF86MonBrightnessDown", exec(linuxSetup .. "/set_brightness.sh 5%-"),             lockedRepeat)

-- Requires playerctl
hl.bind("XF86AudioNext",  exec("playerctl next"),       { locked = true })
hl.bind("XF86AudioPause", exec("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay",  exec("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev",  exec("playerctl previous"),   { locked = true })


--------------------------------
---- WINDOWS AND WORKSPACES ----
--------------------------------

hl.window_rule({ name = "nwg-displays", match = { class = "^(nwg-displays)$", title = "^(nwg-displays)$" }, float = true })

hl.window_rule({
    name  = "pavucontrol",
    match = { class = "^(org.pulseaudio.pavucontrol)$", title = "^(Volume Control)$" },
    float = true,
    size  = "850 500",
})

hl.window_rule({
    name   = "policykit-agent",
    match  = { class = "^(lxqt-policykit-agent)$" },
    float  = true,
    center = true,
    size   = "320 180",
})

hl.window_rule({ name = "vscode-center",  match = { class = "^(Code)$" },                           center = true })
hl.window_rule({ name = "thunar-rename",  match = { class = "^(thunar)$", title = "^(Rename .*)$" }, float = true })
hl.window_rule({ name = "xdg-portal-gtk", match = { class = "^(Xdg-desktop-portal-gtk)$" },          center = true })
hl.window_rule({ name = "bullet-physics", match = { title = "(Bullet Physics.*)" },                  float = true })

-- Global rules

-- prevent idle while an application is fullscreen
hl.window_rule({ name = "idle-inhibit-fullscreen", match = { class = ".*" }, idle_inhibit = "fullscreen" })

-- Ignore maximize requests from apps
hl.window_rule({ name = "suppress-maximize-events", match = { class = ".*" }, suppress_event = "maximize" })

-- Fix some dragging issues with XWayland
hl.window_rule({
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
    },
    no_focus = true,
})
